class TestHealthEndpoint:
    """End-to-end tests for the /health endpoint."""

    def test_health_success(self, client: TestClient) -> None:
        """Verify a successful health check returns 200 with correct schema."""
        response = client.get("/health")
        assert response.status_code == 200

        data = response.json()
        # Response schema validation
        assert "status" in data, "Missing 'status' field"
        assert "version" in data, "Missing 'version' field"
        assert "timestamp" in data, "Missing 'timestamp' field"
        assert "checks" in data, "Missing 'checks' field"

        # Value validation
        assert data["status"] == "healthy"
        assert data["version"] == app.version
        # Timestamp should be ISO 8601 format
        parsed_time = datetime.fromisoformat(data["timestamp"])
        assert parsed_time.tzinfo is not None, "Timestamp must be timezone-aware"

    def test_health_response_headers(self, client: TestClient) -> None:
        """Verify response headers include request ID and content type."""
        response = client.get("/health")
        assert response.status_code == 200
        assert response.headers["content-type"] == "application/json"
        assert "x-request-id" in response.headers, "Missing X-Request-ID header"

    def test_health_request_id_format(self, client: TestClient) -> None:
        """Verify the request ID is a valid UUID."""
        response = client.get("/health")
        request_id = response.headers.get("x-request-id")
        assert request_id is not None
        # Validate UUID format
        try:
            uuid.UUID(request_id)
        except ValueError:
            pytest.fail(f"Request ID '{request_id}' is not a valid UUID")

    def test_health_unique_request_ids(self, client: TestClient) -> None:
        """Verify each request receives a unique request ID."""
        response1 = client.get("/health")
        response2 = client.get("/health")
        id1 = response1.headers.get("x-request-id")
        id2 = response2.headers.get("x-request-id")
        assert id1 != id2, "Request IDs should be unique per request"

    def test_health_failure_returns_500(
        self, client: TestClient, override_dependency, failing_health_service
    ) -> None:
        """Verify a service failure results in a 500 response."""
        override_dependency(failing_health_service)
        response = client.get("/health")
        assert response.status_code == 500

        data = response.json()
        assert "detail" in data, "Error response should contain 'detail'"
        assert "error" in data.get("detail", {}).lower() or "fail" in data.get("detail", "").lower()

    def test_health_failure_logs_error(
        self, client: TestClient, override_dependency, failing_health_service, caplog
    ) -> None:
        """Verify errors are logged with appropriate severity."""
        override_dependency(failing_health_service)
        with caplog.at_level(logging.ERROR):
            response = client.get("/health")
            assert response.status_code == 500
            # Verify error was logged
            error_logs = [r for r in caplog.records if r.levelno == logging.ERROR]
            assert len(error_logs) > 0, "Expected at least one ERROR log entry"
            assert "Database connection refused" in error_logs[0].message


