class TestPerformanceBaseline:
    """Basic performance sanity checks to catch regressions."""

    def test_health_response_time_under_threshold(self, client: TestClient) -> None:
        """
        Verify the /health endpoint responds within 500ms.
        This is a sanity check, not a load test.
        """
        import time

        start = time.perf_counter()
        response = client.get("/health")
        elapsed = time.perf_counter() - start

        assert response.status_code == 200
        assert elapsed < 0.5, f"Response took {elapsed:.3f}s, exceeding 500ms threshold"

    def test_concurrent_health_requests(self, client: TestClient) -> None:
        """
        Verify the endpoint handles 10 sequential requests without degradation.
        """
        import time

        start = time.perf_counter()
        for _ in range(10):
            response = client.get("/health")
            assert response.status_code == 200
        elapsed = time.perf_counter() - start

        # 10 requests should complete in under 2 seconds
        assert elapsed < 2.0, f"10 requests took {elapsed:.3f}s, exceeding 2s threshold"


