class TestHealthStatusModel:
    """Validates the HealthStatus data model."""

    def test_health_status_creation(self) -> None:
        """Verify HealthStatus can be instantiated with valid data."""
        status = HealthStatus(
            status="healthy",
            version="1.0.0",
            timestamp=datetime.now(timezone.utc),
            checks={"database": "ok"},
        )
        assert status.status == "healthy"
        assert status.version == "1.0.0"
        assert status.checks == {"database": "ok"}

    def test_health_status_invalid_status(self) -> None:
        """Verify invalid status values are rejected."""
        with pytest.raises(ValueError):
            HealthStatus(
                status="invalid_status",
                version="1.0.0",
                timestamp=datetime.now(timezone.utc),
                checks={},
            )

    def test_health_status_serialization(self) -> None:
        """Verify HealthStatus can be serialized to a dictionary."""
        status = HealthStatus(
            status="healthy",
            version="1.0.0",
            timestamp=datetime(2026, 7, 31, 12, 0, 0, tzinfo=timezone.utc),
            checks={"database": "ok"},
        )
        data = status.dict() if hasattr(status, "dict") else status.__dict__
        assert data["status"] == "healthy"
        assert data["version"] == "1.0.0"
        assert data["checks"] == {"database": "ok"}